import{c as t,S as f,j as d,m as e}from"./chunks/framework.DI-0jq_N.js";const c=JSON.parse('{"title":"关于我们","description":"","frontmatter":{"title":"关于我们"},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md"}'),l={name:"about/index.md"};function i(r,a,o,v,n,h){return f(),d("div",null,[...a[0]||(a[0]=[e('<h1 id="关于我们" tabindex="-1" data-v-4a7ff47a>关于我们 <a class="header-anchor" href="#关于我们" aria-label="Permalink to &quot;关于我们&quot;" data-v-4a7ff47a>​</a></h1><h2 id="🎮-社团介绍" tabindex="-1" data-v-4a7ff47a>🎮 社团介绍 <a class="header-anchor" href="#🎮-社团介绍" aria-label="Permalink to &quot;🎮 社团介绍&quot;" data-v-4a7ff47a>​</a></h2><p data-v-4a7ff47a>RD STUDIO 是一个热爱游戏开发的学生组织，我们致力于：</p><ul data-v-4a7ff47a><li data-v-4a7ff47a><strong data-v-4a7ff47a>技术分享</strong>：分享游戏开发技术，包括引擎使用、编程技巧、美术制作等</li><li data-v-4a7ff47a><strong data-v-4a7ff47a>学习资源</strong>：提供丰富的学习资源，帮助新手入门游戏开发</li><li data-v-4a7ff47a><strong data-v-4a7ff47a>团队协作</strong>：组织 Game Jam 活动，团队合作开发游戏项目</li></ul><h2 id="📚-我们做什么" tabindex="-1" data-v-4a7ff47a>📚 我们做什么 <a class="header-anchor" href="#📚-我们做什么" aria-label="Permalink to &quot;📚 我们做什么&quot;" data-v-4a7ff47a>​</a></h2><h3 id="技术分享" tabindex="-1" data-v-4a7ff47a>技术分享 <a class="header-anchor" href="#技术分享" aria-label="Permalink to &quot;技术分享&quot;" data-v-4a7ff47a>​</a></h3><p data-v-4a7ff47a>我们定期举办技术分享会，内容涵盖：</p><ul data-v-4a7ff47a><li data-v-4a7ff47a>Unity / Godot / Unreal Engine 使用教程</li><li data-v-4a7ff47a>C# / GDScript / C++ 编程技巧</li><li data-v-4a7ff47a>游戏美术设计（2D / 3D）</li><li data-v-4a7ff47a>游戏音效制作</li></ul><h3 id="game-jam" tabindex="-1" data-v-4a7ff47a>Game Jam <a class="header-anchor" href="#game-jam" aria-label="Permalink to &quot;Game Jam&quot;" data-v-4a7ff47a>​</a></h3><p data-v-4a7ff47a>我们组织和参与各种 Game Jam 活动：</p><ul data-v-4a7ff47a><li data-v-4a7ff47a>社团内部 Game Jam</li><li data-v-4a7ff47a>校级 Game Jam</li><li data-v-4a7ff47a>Global Game Jam</li></ul><h3 id="项目开发" tabindex="-1" data-v-4a7ff47a>项目开发 <a class="header-anchor" href="#项目开发" aria-label="Permalink to &quot;项目开发&quot;" data-v-4a7ff47a>​</a></h3><p data-v-4a7ff47a>我们鼓励社员参与游戏项目开发：</p><ul data-v-4a7ff47a><li data-v-4a7ff47a>个人项目</li><li data-v-4a7ff47a>团队项目</li><li data-v-4a7ff47a>社团项目</li></ul><h2 id="🤝-加入我们" tabindex="-1" data-v-4a7ff47a>🤝 加入我们 <a class="header-anchor" href="#🤝-加入我们" aria-label="Permalink to &quot;🤝 加入我们&quot;" data-v-4a7ff47a>​</a></h2><p data-v-4a7ff47a>如果你对游戏开发感兴趣，欢迎加入我们！</p><h3 id="加入方式" tabindex="-1" data-v-4a7ff47a>加入方式 <a class="header-anchor" href="#加入方式" aria-label="Permalink to &quot;加入方式&quot;" data-v-4a7ff47a>​</a></h3><ol data-v-4a7ff47a><li data-v-4a7ff47a>通过邀请链接注册</li><li data-v-4a7ff47a>联系管理员获取邀请码</li></ol><h3 id="社员福利" tabindex="-1" data-v-4a7ff47a>社员福利 <a class="header-anchor" href="#社员福利" aria-label="Permalink to &quot;社员福利&quot;" data-v-4a7ff47a>​</a></h3><ul data-v-4a7ff47a><li data-v-4a7ff47a>参与内部技术分享</li><li data-v-4a7ff47a>访问内部学习资源</li><li data-v-4a7ff47a>参与 Game Jam 活动</li><li data-v-4a7ff47a>团队合作开发项目</li></ul><h2 id="📞-联系我们" tabindex="-1" data-v-4a7ff47a>📞 联系我们 <a class="header-anchor" href="#📞-联系我们" aria-label="Permalink to &quot;📞 联系我们&quot;" data-v-4a7ff47a>​</a></h2><ul data-v-4a7ff47a><li data-v-4a7ff47a>GitHub: <a href="https://github.com/your-org/game-dev-club" target="_blank" rel="noreferrer" data-v-4a7ff47a>your-org/game-dev-club</a></li><li data-v-4a7ff47a>邮箱: <a href="mailto:contact@example.com" target="_blank" rel="noreferrer" data-v-4a7ff47a>contact@example.com</a></li></ul><h2 id="👥-管理团队" tabindex="-1" data-v-4a7ff47a>👥 管理团队 <a class="header-anchor" href="#👥-管理团队" aria-label="Permalink to &quot;👥 管理团队&quot;" data-v-4a7ff47a>​</a></h2><table tabindex="0" data-v-4a7ff47a><thead data-v-4a7ff47a><tr data-v-4a7ff47a><th data-v-4a7ff47a>角色</th><th data-v-4a7ff47a>姓名</th></tr></thead><tbody data-v-4a7ff47a><tr data-v-4a7ff47a><td data-v-4a7ff47a>社长</td><td data-v-4a7ff47a>张三</td></tr><tr data-v-4a7ff47a><td data-v-4a7ff47a>技术负责人</td><td data-v-4a7ff47a>李四</td></tr><tr data-v-4a7ff47a><td data-v-4a7ff47a>活动负责人</td><td data-v-4a7ff47a>王五</td></tr></tbody></table><hr data-v-4a7ff47a><div class="join-cta" data-v-4a7ff47a><h3 data-v-4a7ff47a>准备好了吗？</h3><p data-v-4a7ff47a>加入我们，一起探索游戏开发的世界！</p><a href="/SiteProject/login" class="btn-primary" data-v-4a7ff47a>立即加入</a></div>',26)])])}const m=t(l,[["render",i],["__scopeId","data-v-4a7ff47a"]]);export{c as __pageData,m as default};
